local GroceryBaseNode = Class("GroceryBaseNode")

--region lifecycle
function GroceryBaseNode:__init()
    self._groceryData    = {}    -- 杂货铺数据
    self._tabState       = false -- 顶部页签启用
    self._selectedTab    = 1     -- 选中的页签
    self._groceryType    = nil   -- 杂货铺类型
    self._refreshSeconds = nil   -- 刷新倒计时
end

function GroceryBaseNode:__delete()
    self._groceryData = nil
    self._tabState    = nil
    self._selectedTab = nil
    self._groceryType = nil
end

function GroceryBaseNode:Awake()
    self:InitHandler()
end

function GroceryBaseNode:Start()
end

function GroceryBaseNode:OnDestroy()
    self:StopTimer()
    Events.RemoveListener(Constants.EventNames.GROCERY_STORE_REFRESH, self._refreshEvent)
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
