--region init
function GroceryBaseNode:InitHandler()
    self._refreshEvent = Events.AddListener(Constants.EventNames.GROCERY_STORE_REFRESH, Bind(self, self.RefreshEventHandler))
end

function GroceryBaseNode:InitData()
    local groceryType = self:InitGroceryType()
    self:SetGroceryType(groceryType)
    
    local groceryData = self:InitGroceryData()
    self:SetGroceryData(groceryData)
    
    local tabState = self:InitTopTabState()
    self:SetTabState(tabState)
    
    local refreshSeconds = self:InitRefreshTimer()
    if refreshSeconds then
        self:SetRefreshSeconds(refreshSeconds)
        self:StartTimer()
    end
end

---初始化UI
function GroceryBaseNode:InitUI()
    self:InitTopTab()
    self:InitCountdown()
end

---初始化顶部页签
function GroceryBaseNode:InitTopTab()
    local tabState = self:GetTabState()
    CfUtils.SetActive(self.CommonTabToggleUp, tabState)
    if not tabState then return end
    
    ---@type CommonTabToggleUp
    local env = CfUtils.GetLuaScr(self.CommonTabToggleUp.gameObject, GroceryConstants.ScrPath.CommonTabToggleUp)
    local togglesData = {}
    for i, v in ipairs(self:GetGroceryData()) do
        table.insert(togglesData, {
            text = v.text,
            func = Bind(self, self.TopTabOnClickHandler),
        })
    end
    env:FillToggles(togglesData)
    self:SetSelectedTab(1)
end

---初始化倒计时
function GroceryBaseNode:InitCountdown()
    CfUtils.SetActive(self.TimerGroup, self:GetRefreshSeconds() and true or false)
end
--endregion init

--region handler
---刷新事件回调
---@param groceryType GroceryConstants.GroceryType
function GroceryBaseNode:RefreshEventHandler(groceryType)
    if groceryType ~= self:GetGroceryType() then return end

    local groceryData = self:InitGroceryData()
    self:SetGroceryData(groceryData)
    self:RefreshUI()
end 

---cell点击回调
function GroceryBaseNode:GroceryCellOnClickHandler(index)
    local data = self:GetGroceryListData()[index]
    GroceryMgr:OpenBuyItemDialog(data, self:GetGroceryType())
end

---页签点击回调
function GroceryBaseNode:TopTabOnClickHandler(index)
    self:SetSelectedTab(index)
    self:RefreshUI()
end

---杂货铺物品列表处理
function GroceryBaseNode:OnGetItemByIndex(cell, idx)
    if idx < 0 then return nil end

    ---@type GroceryBaseNodeListCell
    local nodeScr = CfUtils.GetLuaScr(cell, GroceryConstants.ScrPath.GroceryBaseNodeListCell)
    if isNull(nodeScr) then return nil end
    
    local index = idx + 1
    local data = self:GetGroceryListData()[index]
    nodeScr:SetClickCallback(Bind(self, self.GroceryCellOnClickHandler))
    nodeScr:RefreshCell(data, index)
    
    return cell
end
--endregion handler

--region public
---刷新UI
function GroceryBaseNode:RefreshUI()
    self:RefreshItemList()
end
--endregion public

--region private
---刷新列表
function GroceryBaseNode:RefreshItemList()
    local groceryData = self:GetGroceryListData()
    if not self.ScrollView.mLoopListView.IsListViewInit then
        self.ScrollView:InitListView(#groceryData, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, #groceryData)
        self.ScrollView:MovePanelToItemIndex(0)
    end
end

---开启定时器
function GroceryBaseNode:StartTimer()
    if self._refreshTimer then
        self:StopTimer()
    end
    
    self._refreshTimer = CDTimerModule:AddCD(1, Bind(self, self.OnUpdate), self:GetRefreshSeconds(),true, true, true)    
end

---停止定时器
function GroceryBaseNode:StopTimer()
    if self._refreshTimer then
        CDTimerModule:RemoveCD(self._refreshTimer)
        self._refreshTimer = nil
    end
end

---定时器更新
function GroceryBaseNode:OnUpdate(count, id)
    self:SetRefreshSeconds(count)
    self:RefreshCountdown()
    if count == 0 then
        Events.Broadcast(Constants.EventNames.GROCERY_HOME_REFRESH)
    end
end

---刷新倒计时
function GroceryBaseNode:RefreshCountdown()
    local seconds = checkInt(self:GetRefreshSeconds())
    if seconds > 0 then
        local text = CfUtils.GetTimeHMS4(seconds)
        CfUtils.FillText(self.RefreshTimer, text)
    end
end 

--endregion private

